          "kubectl create secret generic jwt-key --from-file=key.pem=/path/to/new/key.pem -n inventory --dry-run=client -o yaml | kubectl apply -f -",
          "kubectl rollout restart deployment/inventory-api -n inventory"
        ],
        "verification": [
          "Secret 'jwt-key' contains the new key fingerprint",
          "All inventory-api pods reach READY=1/1 within 5 minutes"
        ]
      },
