          "promtool query instant \"rate(http_requests_total{service='inventory-api',code='5..'}[5m])\""
        ],
        "verification": [
          "Health endpoint returns 'OK'",
          "All pods report ready=true",
          "Error rate metric is < 0.01 requests per second"
