          "title": "Restore Previous JWT Key Secret",
          "description": "Reapply the prior secret version from backup.",
          "commands": [
            "kubectl apply -f /backups/jwt-key-backup.yaml"
          ],
          "verification": [
            "Secret 'jwt-key' matches backup fingerprint"
          ]
